type ParseResult<T> =
  | { ok: true; value: T }
  | { ok: false; issues: readonly string[] };

function parsePort(input: string): ParseResult<number> {
  const value = Number(input);
  return Number.isInteger(value) && value > 0 && value <= 65_535
    ? { ok: true, value }
    : { ok: false, issues: ['Expected a valid TCP port'] };
}

